-- Helper RPC: run arbitrary DDL from the proxy (service-role only).\n-- This is used by the auto-migration logic in crm-proxy to add missing\n-- columns on the fly when migrations haven't been applied yet.\nCREATE OR REPLACE FUNCTION public.exec_sql(q TEXT)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n  EXECUTE q;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.exec_sql(TEXT) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.exec_sql(TEXT) TO service_role;\n